import { it } from 'vitest';
import { writeFileSync } from 'node:fs';
import { KIT_RULES, grade, receipt, receiptText, repairPlan, fromPage, designId, checkBrief, placeholderIn } from '../src/index.js';
import type { Finding } from '../src/index.js';
const lines: string[] = [];
const out = (label: string, v: unknown): void => { lines.push(`${label}: ${typeof v === 'string' ? v : JSON.stringify(v)}`); };
const timed = (label: string, fn: () => unknown): void => { const t = Date.now(); let r: unknown; try { r = fn(); } catch (e) { r = `THROWS ${String(e).slice(0, 120)}`; } out(`${label} [${((Date.now() - t) / 1000).toFixed(1)} s]`, r); };
const BRIEF = { businessName: 'Reagan Dental', whatItDoes: 'We clean and repair teeth for families.', audience: 'Families in Denver', mainJob: 'Book a visit', headline: 'Gentle care for every tooth', services: [{ name: 'Cleaning', description: 'A full cleaning by a hygienist.' }, { name: 'Fillings', description: 'Tooth-colored fillings in one visit.' }, { name: 'Crowns', description: 'Crowns made in our own lab.' }], contact: { phone: '303-555-1212' }, proof: [{ text: 'They fixed my tooth in a day.' }], voice: { tone: 'friendly', length: 'brief', stance: 'modest' }, wordsToAvoid: [] as string[] };
void [KIT_RULES, grade, receipt, receiptText, repairPlan, fromPage, designId, checkBrief, placeholderIn, timed, BRIEF];
it('sec', () => {
  const all = (status: 'holds'): Finding[] => KIT_RULES.map((r) => ({ ruleId: r.id, status }));
  const person = new Set(KIT_RULES.filter((r) => r.check.kind === 'person').map((r) => r.id));
  const floor = KIT_RULES.find((r) => r.level === 'floor' && r.check.kind !== 'person')!.id;
  out('one program floor missing', grade(all('holds').filter((f) => f.ruleId !== floor), KIT_RULES).grade);
  out('one floor holds and could-not-measure', grade([...all('holds'), { ruleId: floor, status: 'could-not-measure' }], KIT_RULES).grade);
  out('one floor holds and fails', grade([...all('holds'), { ruleId: floor, status: 'fails' }], KIT_RULES).grade);
  out('person floors open', grade(all('holds').filter((f) => !person.has(f.ruleId)), KIT_RULES).grade);
  out('person floors answered', grade(all('holds'), KIT_RULES).grade);
  out('unknown rule beside a clean set', grade([...all('holds'), { ruleId: 'nope', status: 'holds' }], KIT_RULES).grade);
  out('floor fails in round 1, could-not-measure in round 2: stillOpen', repairPlan([[{ ruleId: floor, status: 'fails', where: 'a' }], [{ ruleId: floor, status: 'could-not-measure' }]], KIT_RULES).stillOpen);
  writeFileSync('sec-out.txt', lines.join('\n') + '\n');
}, 600000);

